     *
     * @see java.util.logging.Level
     * @param level
     * @return
     */
    public static Level level(Level level) {
        Level old = LEVEL;
        LEVEL = level;
        return old;
    }

    /**
     * get current logger Level
     *
     * @return
     */
    public static Level level() {
